     6→/* ---------- CSS Custom Properties ---------- */
     7→:root,
     8→[data-theme="dark"] {
     9→  --color-bg:            #050c1a;
    10→  --color-bg-alt:        #08121f;
    11→  --color-surface:       #0e1d32;
    12→  --color-surface-2:     #152440;
    13→  --color-surface-3:     #1a2d4e;
    14→
    15→  --color-primary:       #00c8b4;
    16→  --color-primary-dark:  #00a898;
    17→  --color-primary-light: rgba(0, 200, 180, 0.12);
    18→
    19→  --color-accent:        #f0a500;
    20→  --color-accent-dark:   #c98a00;
    21→  --color-accent-light:  rgba(240, 165, 0, 0.12);
    22→
    23→  --color-purple:        #8b5cf6;
    24→  --color-purple-light:  rgba(139, 92, 246, 0.12);
    25→
    26→  --color-text:          #e2ecf8;
    27→  --color-text-muted:    #7a9abd;
    28→  --color-text-faint:    #3d5a78;
    29→
    30→  --color-border:        rgba(255, 255, 255, 0.07);
    31→  --color-border-strong: rgba(255, 255, 255, 0.13);
    32→  --color-card-bg:       rgba(14, 29, 50, 0.85);
    33→
    34→  /* publication type colours */
    35→  --color-q1:            #00c8b4;
    36→  --color-q1-bg:         rgba(0, 200, 180, 0.15);
    37→  --color-q2:            #60a5fa;
