    45→
    46→  --nav-height:          68px;
    47→  --progress-color:      var(--color-primary);
    48→}
    49→
    50→[data-theme="light"] {
    51→  --color-bg:            #f8fbff;
    52→  --color-bg-alt:        #eef4fc;
    53→  --color-surface:       #ffffff;
    54→  --color-surface-2:     #f0f6ff;
    55→  --color-surface-3:     #e8f1fc;
    56→
    57→  --color-primary:       #007d72;
    58→  --color-primary-dark:  #006059;
    59→  --color-primary-light: rgba(0, 125, 114, 0.10);
    60→
    61→  --color-accent:        #b07400;
    62→  --color-accent-dark:   #8a5c00;
    63→  --color-accent-light:  rgba(176, 116, 0, 0.10);
    64→
    65→  --color-purple:        #6d28d9;
    66→  --color-purple-light:  rgba(109, 40, 217, 0.10);
    67→
    68→  --color-text:          #0d1e38;
    69→  --color-text-muted:    #426080;
    70→  --color-text-faint:    #8ca8c0;
    71→
    72→  --color-border:        rgba(0, 0, 0, 0.08);
    73→  --color-border-strong: rgba(0, 0, 0, 0.14);
    74→  --color-card-bg:       #ffffff;
    75→
    76→  --color-q1:            #006b60;
    77→  --color-q1-bg:         rgba(0, 107, 96, 0.10);
    78→  --color-q2:            #1d4ed8;
    79→  --color-q2-bg:         rgba(29, 78, 216, 0.10);
    80→  --color-thesis:        #7c3aed;
    81→  --color-thesis-bg:     rgba(124, 58, 237, 0.10);
    82→  --color-conf:          #92400e;
    83→  --color-conf-bg:       rgba(146, 64, 14, 0.10);
    84→  --color-preprint:      #be185d;
    85→  --color-preprint-bg:   rgba(190, 24, 93, 0.10);
    86→}
    87→
    88→/* ---------- Fonts ---------- */
    89→:root {
    90→  --font-display: 'Playfair Display', Georgia, 'Times New Roman', serif;
    91→  --font-sans:    'Source Sans 3', 'Helvetica Neue', system-ui, sans-serif;
    92→  --font-mono:    'JetBrains Mono', 'Fira Code', Consolas, monospace;
    93→
    94→  --radius-xs:   4px;
    95→  --radius-sm:   8px;
    96→  --radius-md:   14px;
    97→  --radius-lg:   22px;
    98→  --radius-xl:   32px;
    99→  --radius-full: 9999px;
   100→
   101→  --shadow-sm:  0 2px 8px rgba(0,0,0,0.12);
   102→  --shadow-md:  0 8px 32px rgba(0,0,0,0.18), 0 2px 8px rgba(0,0,0,0.12);
   103→  --shadow-lg:  0 20px 60px rgba(0,0,0,0.28), 0 6px 20px rgba(0,0,0,0.16);
   104→  --shadow-glow: 0 0 40px rgba(0, 200, 180, 0.18);
   105→
   106→  --transition: 0.22s ease;
   107→  --transition-slow: 0.4s ease;
   108→}
   109→
   110→[data-theme="light"] {
   111→  --shadow-sm:  0 2px 8px rgba(0,0,0,0.06);
   112→  --shadow-md:  0 8px 32px rgba(0,0,0,0.10), 0 2px 8px rgba(0,0,0,0.06);
   113→  --shadow-lg:  0 20px 60px rgba(0,0,0,0.12), 0 6px 20px rgba(0,0,0,0.08);
   114→  --shadow-glow: 0 0 40px rgba(0, 125, 114, 0.15);
   115→}
   116→
   117→/* ---------- Reset & Base ---------- */
   118→*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
   119→
   120→html {
   121→  scroll-behavior: smooth;
   122→  font-size: 16px;
   123→  -webkit-text-size-adjust: 100%;
   124→}
   125→
   126→body {
   127→  font-family: var(--font-sans);
   128→  color: var(--color-text);
   129→  background: var(--color-bg);
   130→  line-height: 1.7;
   131→  -webkit-font-smoothing: antialiased;
   132→  -moz-osx-font-smoothing: grayscale;
   133→  transition: background var(--transition-slow), color var(--transition-slow);
   134→  overflow-x: hidden;
   135→}
   136→
   137→img { max-width: 100%; display: block; }
   138→a  { color: var(--color-primary); text-decoration: none; }
   139→a:hover { text-decoration: underline; }
   140→button { cursor: pointer; font-family: var(--font-sans); }
   141→
   142→/* ---------- Scroll Progress Bar ---------- */
   143→#scroll-progress {
   144→  position: fixed;
   145→  top: 0;
   146→  left: 0;
   147→  height: 3px;
   148→  width: 0%;
   149→  background: linear-gradient(90deg, var(--color-primary), var(--color-accent));
   150→  z-index: 9999;
   151→  transition: width 0.1s linear;
   152→  border-radius: 0 var(--radius-full) var(--radius-full) 0;
   153→}
   154→
   155→/* ---------- Utilities ---------- */
   156→.container {
   157→  max-width: 1100px;
   158→  margin: 0 auto;
   159→  padding: 0 28px;
   160→}
   161→
   162→.inline-link {
   163→  color: var(--color-primary);
   164→  font-weight: 500;
   165→  border-bottom: 1px solid transparent;
   166→  transition: border-color var(--transition);
   167→}
   168→.inline-link:hover { text-decoration: none; border-bottom-color: var(--color-primary); }
   169→
   170→/* ---------- Buttons ---------- */
   171→.btn {
   172→  display: inline-flex;
   173→  align-items: center;
   174→  gap: 7px;
   175→  padding: 10px 22px;
   176→  border-radius: var(--radius-full);
   177→  font-size: 0.875rem;
   178→  font-weight: 600;
   179→  font-family: var(--font-sans);
   180→  cursor: pointer;
   181→  transition: all var(--transition);
   182→  border: 2px solid transparent;
   183→  text-decoration: none !important;
   184→  white-space: nowrap;
   185→  letter-spacing: 0.01em;
   186→}
   187→.btn:hover { transform: translateY(-2px); text-decoration: none; }
   188→.btn:active { transform: translateY(0); }
   189→
   190→.btn-primary {
   191→  background: var(--color-primary);
   192→  color: #050c1a;
   193→  border-color: var(--color-primary);
   194→}
   195→[data-theme="light"] .btn-primary { color: #ffffff; }
   196→.btn-primary:hover { background: var(--color-primary-dark); border-color: var(--color-primary-dark); box-shadow: 0 4px 20px rgba(0, 200, 180, 0.35); }
